(()=>{'use strict';if(window.pbLabSessionWatch||window.pbNativeStorage||!window.fetch||!window.AbortController)return;window.pbLabSessionWatch=true;
 let busy=false,closed=false,redirecting=false,last=0,controller=null,interval=null,generation=0;
 function principal(){let token='',context=null;try{token=sessionStorage.getItem('lablink_test_session')||'';context=JSON.parse(sessionStorage.getItem('photobridge_admin_impersonation')||'null');}catch{}const headers={'x-photobridge-portal':'lab','Cache-Control':'no-cache'};if(token){headers.authorization='Bearer '+token;if(context){headers['x-photobridge-impersonation']='1';if(context.role==='lab'&&context.labId)headers['x-photobridge-impersonation-lab-id']=String(context.labId);}}return {token,headers,key:JSON.stringify([token,context?.role||'',context?.labId||''])};}
 function workspace(){return /^\/lab(?:\/|$)/.test(location.pathname)&&document.querySelector('.labRoleWorkspace');}
 async function check(force=false){const root=workspace();if(closed||redirecting||busy||!root||document.visibilityState==='hidden'||!force&&Date.now()-last<2500)return;busy=true;last=Date.now();const runGeneration=generation,identity=principal();controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),4000);
  try{const response=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store',headers:identity.headers,signal:controller.signal});let expired=response.status===401;if(response.ok){try{expired=await response.json()===null;}catch{}}
   if(expired&&!closed&&runGeneration===generation&&root===workspace()&&identity.key===principal().key){redirecting=true;if(identity.token){try{sessionStorage.removeItem('lablink_test_session');sessionStorage.removeItem('photobridge_admin_impersonation');}catch{}}location.replace('/lab?sessionExpired=1');}
  }catch{}finally{clearTimeout(timeout);controller=null;busy=false;}
 }
 interval=setInterval(()=>void check(),3000);new MutationObserver(()=>void check()).observe(document.documentElement,{childList:true,subtree:true});addEventListener('focus',()=>void check(true));addEventListener('pageshow',()=>{closed=false;clearInterval(interval);interval=setInterval(()=>void check(),3000);void check(true)});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')void check(true)});addEventListener('pagehide',()=>{closed=true;generation++;clearInterval(interval);controller?.abort();});void check();
})();
